"""X23: generated files are skipped - by name before reading, by marker after.

Measured: 97% of one .NET repo's C# was EF migrations and designer files, most of
a cold read's time, saying nothing a person wired between repos.
"""

from __future__ import annotations

import pytest

from gingugu.xray.links import generated, index
from tests.test_xray_links_index import eco  # noqa: F401 - the fixture


@pytest.mark.parametrize(
    "path",
    [
        "Api/Migrations/20231003_Init.cs",
        "Api/Migrations/20231003_Init.Designer.cs",
        "Ui/Forms/Main.Designer.cs",
        "obj/Views/Index.g.cs",
        "web/dist/app.min.js",
        "proto/svc_pb2.py",
        "api/v1/svc.pb.go",
        "pkg/apis/zz_generated.deepcopy.go",
        "app/db/migrations/0001_initial.py",
    ],
)
def test_generated_by_name(path):
    assert generated.by_name(path)


@pytest.mark.parametrize(
    "path",
    ["src/Migrations.md", "docs/migrations/how-to.md", "src/designer.ts", "k8s/migrations.yaml"],
)
def test_not_generated_by_name(path):
    assert not generated.by_name(path)


@pytest.mark.parametrize(
    "head",
    [
        "// <auto-generated>\n//     This code was generated by a tool.\n",
        "// Code generated by protoc-gen-go. DO NOT EDIT.\n",
        "/* @generated */\n",
        "# This file was automatically generated by SWIG\n",
    ],
)
def test_generated_by_head(head):
    assert generated.by_head(head + "x = 1\n")


def test_a_marker_far_down_is_a_mention_not_a_header():
    assert not generated.by_head("x = 1\n" * 1000 + "# Code generated by x DO NOT EDIT\n")


def test_the_index_never_extracts_a_generated_file(eco):  # noqa: F811
    a, state = eco
    (a / "svc/Migrations").mkdir()
    (a / "svc/Migrations/1_Init.cs").write_text('var u = "https://leak.acme.io/x/y";\n')
    (a / "svc/gen.py").write_text(
        "# @generated by hand-rolled tool\nURL = 'https://leak2.acme.io/a/b'\n"
    )
    calls = []

    def counting(path, text):
        calls.append(path)
        return index._default_extract(path, text)

    e = index.read(a, state, budget_s=10, extract=counting)
    assert "svc/Migrations/1_Init.cs" not in calls and "svc/gen.py" not in calls
    hosts = {f.key for f in e.repos["acme/svc-a"].mentioned}
    assert "leak.acme.io" not in hosts and "leak2.acme.io" not in hosts
